-- K-9 inh — 상속·증여·가업상속·종부세·법인세 성분 86행 (적용: MCP apply_migration k9_inh_policy_constants_2026_09_17)
-- 원문: 국가법령정보센터 DRF eflaw «현행 시행본»(lawService target=eflaw, MST+그 판의 시행일자) 직접 대조 2026-09-17.
--   상속세 및 증여세법 MST 276123(시행 2026-01-02; 해당 조문 법률 21219 판과 동일, 시행예정 판 없음)
--   종합부동산세법 MST 280417(2026-01-01, 시행예정 없음) · 시행령 MST 283639(2026-02-27) · 농어촌특별세법 MST 285905(2026-05-12)
--   법인세법 MST 280349(법률 21217, 현행판 2026-07-01; §55 는 2027·2028 시행예정 판과 동일) · 종전 MST 276111(법률 21065)
--   지방세법 MST 282559(2026-07-01; §103의20 은 2027-01-01·2027-09-09 시행예정 판과 동일)
-- 누진표 구간 «경계» 도 행이다(*_upto_*). 구간 기본세액은 경계·세율의 연속으로 유도하고 원문 표 금액과 테스트(k9-inh.test.ts)로 일치를 고정.
-- ⚠️ 접두 LIKE 충돌 사전 실측: inh_% gift_% biz_inh_% cpt_% corp_tax_% corp_ltax_% → 기존 0행(2026-09-17). pit_·cgt_ 는 만들지 않았다(공유표·타 워커 몫).
-- 말미 단언: 접두별 행 수 정확 일치, 불일치면 RAISE → 전체 롤백.

DO $$
DECLARE n_inh int; n_biz int; n_gift int; n_cpt int; n_corp int; n_ltax int;
BEGIN
  SELECT count(*) INTO n_inh  FROM policy_constants WHERE key LIKE 'inh\_%';
  SELECT count(*) INTO n_biz  FROM policy_constants WHERE key LIKE 'biz\_inh\_%';
  SELECT count(*) INTO n_gift FROM policy_constants WHERE key LIKE 'gift\_%';
  SELECT count(*) INTO n_cpt  FROM policy_constants WHERE key LIKE 'cpt\_%';
  SELECT count(*) INTO n_corp FROM policy_constants WHERE key LIKE 'corp\_tax\_%';
  SELECT count(*) INTO n_ltax FROM policy_constants WHERE key LIKE 'corp\_ltax\_%';
  IF n_inh <> 21 OR n_biz <> 4 OR n_gift <> 10 OR n_cpt <> 31 OR n_corp <> 19 OR n_ltax <> 1 THEN
    RAISE EXCEPTION 'k9 inh 행 수 불일치: inh % biz % gift % cpt % corp % ltax %', n_inh, n_biz, n_gift, n_cpt, n_corp, n_ltax;
  END IF;
END $$;
